{
   if(!_parent._parent.useAI)
   {
      return _parent.kis(_parent.斩);
   }
   if(combo === true)
   {
      if(_root.game["p" + _parent.pn].mc.动作 == -1)
      {
         return _parent.attran < 120;
      }
