   }
   if(_root.game["p" + _parent.pn].mc.动作 < 3)
   {
      if(_root.game["p" + _parent.pn]._y < _parent._parent._y - 20)
      {
         return _parent.jumpran < 100;
      }
      return _parent.jumpran > 100 && _parent.jumpran < 130;
   }
   return false;
