function setColor(o)
{
   var _loc1_ = new Color(_this);
   _loc1_.setTransform(o);
}
function resColor()
{
   colors = null;
   _cgap = 1;
   setColor({ra:100,rb:0,ga:100,gb:0,ba:100,bb:0,aa:100,ab:0});
   _this.filters = [];
}
function applyColors()
{
   if(colors && colors.length > 0)
   {
      setColor(colors[_csn]);
      if(++_csn > colors.length - 1)
      {
         _csn = 0;
      }
   }
}
function initWudi()
{
   if(_initwudi)
   {
      return undefined;
   }
   if(!_root.wudi)
   {
      return undefined;
   }
   if(_root.modo == undefined || _parent.useAI == undefined)
   {
      return undefined;
   }
   trace("initwudi" + _root.modo + "," + _parent.useAI);
   _initwudi = true;
   wudi = _root.modo == 1 && _parent.useAI == false;
   if(wudi)
   {
      ql = 300;
   }
}
function followMc(mc, fx, fy, lockx)
{
   trace("followMc , " + fx + "," + fy + "," + lockx);
   if(fx == undefined)
   {
      fx = true;
   }
   if(fy == undefined)
   {
      fy = true;
   }
   if(lockx == undefined)
   {
      lockx = false;
   }
   if(fx == true)
   {
      if(_parent._xscale > 0)
      {
         if(lockx == true)
         {
            if(_parent._x < _root.game["p" + pn]._x)
            {
               mc._x = _root.game["p" + pn]._x - _parent._x;
            }
         }
         else
         {
            mc._x = _root.game["p" + pn]._x - _parent._x;
         }
      }
      else if(lockx == true)
      {
         if(_parent._x > _root.game["p" + pn]._x)
         {
            mc._x = _parent._x - _root.game["p" + pn]._x;
         }
      }
      else
      {
         mc._x = _parent._x - _root.game["p" + pn]._x;
      }
   }
   if(fy == true)
   {
      mc._y = _root.game["p" + pn]._y - _parent._y;
   }
}
function doWanKai()
{
   initCtrl();
   if(_parent.万解)
   {
      hp = _parent.中转.hp;
      ql = _parent.中转.ql;
      if(_parent._name == "p1")
      {
         trace("p1");
         _this.上 = _root.w;
         _this.下 = _root.s;
         _this.左 = _root.a;
         _this.右 = _root.d;
         _this.斩 = _root.j;
         _this.跳 = _root.k;
         _this.冲 = _root.l;
         _this.招 = _root.u;
         _this.必杀 = _root.i;
         _this.换 = _root.o;
      }
      else
      {
         trace("p2");
         _this.上 = _root.上箭;
         _this.下 = _root.下箭;
         _this.左 = _root.左箭;
         _this.右 = _root.右箭;
